package postgres

import (
	"context"
	"fmt"

	"github.com/deepworx/go-utils/pkg/ctxutil"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// UnitOfWork runs a function inside a transaction carried by its context.
// An already open transaction in ctx is joined silently.
type UnitOfWork interface {
	Execute(ctx context.Context, fn func(ctx context.Context) error) error
}

// Querier is the query surface shared by pgx.Tx and *pgxpool.Pool. It is
// compatible with the DBTX interface generated by sqlc for pgx/v5.
type Querier interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
	CopyFrom(ctx context.Context, tableName pgx.Identifier, columnNames []string, rowSrc pgx.CopyFromSource) (int64, error)
}

// TxFromContext returns the transaction opened by PgUnitOfWork.Execute, or
// nil outside one.
func TxFromContext(ctx context.Context) pgx.Tx {
	tx, _ := ctx.Value(pgTxKey{}).(pgx.Tx)
	return tx
}

// Conn returns the open transaction from ctx, or pool outside one. Pass the
// result to sqlc's New so queries run inside the UnitOfWork when there is one.
func Conn(ctx context.Context, pool *pgxpool.Pool) Querier {
	if tx := TxFromContext(ctx); tx != nil {
		return tx
	}
	return pool
}

type pgTxKey struct{}

func withTx(ctx context.Context, tx pgx.Tx) context.Context {
	return context.WithValue(ctx, pgTxKey{}, tx)
}

// UnitOfWorkOption configures a PgUnitOfWork.
type UnitOfWorkOption func(*PgUnitOfWork)

// TxOptions sets the options used to begin each transaction.
func TxOptions(opts pgx.TxOptions) UnitOfWorkOption {
	return func(u *PgUnitOfWork) { u.txOptions = opts }
}

// SetLocalTenant makes each transaction issue SET LOCAL app.tenant_id with
// the Tenant from ctxutil.TenantID, so row-level security policies can read
// it via current_setting('app.tenant_id', true). Without a Tenant in ctx the
// setting stays unset. Off by default.
func SetLocalTenant() UnitOfWorkOption {
	return func(u *PgUnitOfWork) { u.setLocalTenant = true }
}

// PgUnitOfWork implements UnitOfWork with a PostgreSQL transaction stored in
// the context.
type PgUnitOfWork struct {
	pool           *pgxpool.Pool
	txOptions      pgx.TxOptions
	setLocalTenant bool
}

// NewUnitOfWork creates a UnitOfWork backed by the given connection pool.
func NewUnitOfWork(pool *pgxpool.Pool, opts ...UnitOfWorkOption) *PgUnitOfWork {
	u := &PgUnitOfWork{pool: pool}
	for _, opt := range opts {
		opt(u)
	}
	return u
}

// Execute runs fn in a transaction available through TxFromContext and Conn.
// It commits when fn returns nil and rolls back on error or panic. If ctx
// already carries a transaction, fn joins it and the outer Execute decides
// the outcome.
func (u *PgUnitOfWork) Execute(ctx context.Context, fn func(ctx context.Context) error) error {
	if TxFromContext(ctx) != nil {
		return fn(ctx)
	}
	return runTx(ctx, txInput{pool: u.pool, opts: u.txOptions, fn: func(tx pgx.Tx) error {
		if err := u.applyTenant(ctx, tx); err != nil {
			return err
		}
		return fn(withTx(ctx, tx))
	}})
}

func (u *PgUnitOfWork) applyTenant(ctx context.Context, tx pgx.Tx) error {
	if !u.setLocalTenant {
		return nil
	}
	tenant, ok := ctxutil.TenantID(ctx)
	if !ok {
		return nil
	}
	if _, err := tx.Exec(ctx, `SELECT set_config('app.tenant_id', $1, true)`, tenant); err != nil {
		return fmt.Errorf("set local app.tenant_id: %w", err)
	}
	return nil
}

var _ UnitOfWork = (*PgUnitOfWork)(nil)
